"""Text of every generated file: odoo.conf, systemd, nginx, logrotate and IDE configs."""

from __future__ import annotations

import json
import shlex
from pathlib import Path
from xml.sax.saxutils import quoteattr

from .models import Instance


def addons_path(instance: Instance) -> list[Path]:
    """Enterprise first (it overrides community), then custom modules, then community."""
    from .repos import custom_addons_paths

    paths = []
    if instance.enterprise_dir is not None:
        paths.append(instance.enterprise_dir)
    paths += custom_addons_paths(instance.custom_dir)
    paths.append(instance.community_dir / "addons")
    paths.append(instance.community_dir / "odoo" / "addons")
    return paths


def odoo_conf(instance: Instance, *, db_password: str, master_password: str, workers: int = 0) -> str:
    lines = [
        "; Generated by odoobuddy. Edit freely, then restart the instance.",
        "[options]",
        # Master password: protects the database manager (create / backup / delete databases).
        f"admin_passwd = {master_password}",
        "db_host = localhost",
        "db_port = 5432",
        f"db_user = {instance.db_user}",
        f"db_password = {db_password}",
        f"addons_path = {','.join(str(p) for p in addons_path(instance))}",
        f"data_dir = {instance.data_dir}",
        f"http_port = {instance.backend_http_port}",
        f"gevent_port = {instance.backend_gevent_port}",
    ]
    if instance.mode == "server":
        lines += [
            f"logfile = {instance.log_path}",
            "proxy_mode = True",
            "http_interface = 127.0.0.1",  # only reachable through Nginx
            f"workers = {workers}",
            "max_cron_threads = 1",
            "limit_memory_soft = 2147483648",
            "limit_memory_hard = 2684354560",
            "limit_time_cpu = 600",
            "limit_time_real = 1200",
        ]
    else:
        # No logfile locally: logs go to the terminal / IDE. `odoobuddy start` adds one.
        lines += ["workers = 0", "dev_mode = reload,xml"]
    return "\n".join(lines) + "\n"


def systemd_unit(instance: Instance) -> str:
    return f"""\
[Unit]
Description=Odoo {instance.version} ({instance.name}) - managed by odoobuddy
Requires=postgresql.service
After=network.target postgresql.service

[Service]
Type=simple
User={instance.system_user}
Group={instance.system_user}
ExecStart={instance.python_bin} {instance.odoo_bin} -c {instance.config_path}
Restart=on-failure
RestartSec=5
KillMode=mixed
StandardOutput=journal+console

[Install]
WantedBy=multi-user.target
"""


def backup_service(instance: Instance, odoobuddy: list[str], keep: int, dest: Path | None = None) -> str:
    to = ["--to", str(dest)] if dest else []
    command = shlex.join([*odoobuddy, "backup", instance.name, "--all", "--keep", str(keep), *to])
    return f"""\
[Unit]
Description=Back up every database of Odoo instance {instance.name} - managed by odoobuddy
Requires=postgresql.service
After=postgresql.service

[Service]
Type=oneshot
ExecStart={command}
# A backup must not slow Odoo down for its users.
Nice=10
IOSchedulingClass=idle
"""


def backup_timer(instance: Instance) -> str:
    return f"""\
[Unit]
Description=Nightly backup of Odoo instance {instance.name} - managed by odoobuddy

[Timer]
OnCalendar=*-*-* 02:30
# Spread instances out, so their backups do not all run at the same moment.
RandomizedDelaySec=30min
# Run at boot when the server was off at 02:30.
Persistent=true

[Install]
WantedBy=timers.target
"""


def nginx_site(instance: Instance) -> str:
    key = instance.name.replace("-", "_")
    if instance.domain:
        listen = f"    listen 80;\n    listen [::]:80;\n    server_name {instance.domain};"
    else:
        port = instance.http_port
        listen = f"    listen {port};\n    listen [::]:{port};\n    server_name _;"
    headers = """\
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Real-IP $remote_addr;"""
    return f"""\
# Generated by odoobuddy for instance "{instance.name}" (Odoo {instance.version}).
upstream odoo_{key} {{
    server 127.0.0.1:{instance.backend_http_port};
}}
upstream odoo_{key}_ws {{
    server 127.0.0.1:{instance.backend_gevent_port};
}}
map $http_upgrade $odoo_{key}_connection_upgrade {{
    default upgrade;
    ''      close;
}}

server {{
{listen}

    client_max_body_size 200m;
    proxy_read_timeout 720s;
    proxy_connect_timeout 720s;
    proxy_send_timeout 720s;

    access_log /var/log/nginx/odoo-{instance.name}.access.log;
    error_log /var/log/nginx/odoo-{instance.name}.error.log;

    location /websocket {{
        proxy_pass http://odoo_{key}_ws;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $odoo_{key}_connection_upgrade;
{headers}
    }}

    location / {{
        proxy_pass http://odoo_{key};
        proxy_redirect off;
{headers}
    }}

    gzip on;
    gzip_types text/css text/scss text/plain text/xml application/xml application/json application/javascript;
}}
"""


def logrotate(instance: Instance) -> str:
    return f"""\
{instance.log_path} {{
    weekly
    rotate 8
    compress
    delaycompress
    missingok
    notifempty
    copytruncate
}}
"""


def vscode_launch(instance: Instance) -> str:
    config = {
        "version": "0.2.0",
        "configurations": [
            {
                # Odoo already runs (started by the folder-open task): attach without restarting.
                "name": f"Attach to Odoo ({instance.name})",
                "type": "debugpy",
                "request": "attach",
                "connect": {"host": "127.0.0.1", "port": instance.debug_port},
                "justMyCode": False,
            },
            {
                "name": f"Debug Odoo from start ({instance.name}) - stop the running task first",
                "type": "debugpy",
                "request": "launch",
                "program": str(instance.odoo_bin),
                "args": ["-c", str(instance.config_path)],
                "python": str(instance.python_bin),
                "console": "integratedTerminal",
                "justMyCode": False,
            },
            {
                "name": f"Odoo shell ({instance.name})",
                "type": "debugpy",
                "request": "launch",
                "program": str(instance.odoo_bin),
                "args": ["shell", "-c", str(instance.config_path)],
                "python": str(instance.python_bin),
                "console": "integratedTerminal",
                "justMyCode": False,
            },
        ],
    }
    return json.dumps(config, indent=4) + "\n"


def vscode_settings(instance: Instance) -> str:
    settings = {
        "python.defaultInterpreterPath": str(instance.python_bin),
        "python.analysis.extraPaths": [str(instance.community_dir)] + [str(p) for p in addons_path(instance)],
        "files.exclude": {"venv": True, "data": True, "**/__pycache__": True},
        "search.exclude": {"venv": True, "data": True},
        # Start Odoo when the folder opens (the editor may still ask once for permission).
        "task.allowAutomaticTasks": "on",
    }
    return json.dumps(settings, indent=4) + "\n"


def vscode_extensions() -> str:
    return json.dumps({"recommendations": ["ms-python.python", "ms-python.debugpy"]}, indent=4) + "\n"


def pycharm_run_config(instance: Instance) -> str:
    name = quoteattr(f"Odoo {instance.version} ({instance.name})")
    return f"""\
<component name="ProjectRunConfigurationManager">
  <configuration default="false" name={name} type="PythonConfigurationType" factoryName="Python">
    <option name="INTERPRETER_OPTIONS" value="" />
    <option name="PARENT_ENVS" value="true" />
    <option name="SDK_HOME" value={quoteattr(str(instance.python_bin))} />
    <option name="WORKING_DIRECTORY" value={quoteattr(str(instance.instance_dir))} />
    <option name="IS_MODULE_SDK" value="false" />
    <option name="ADD_CONTENT_ROOTS" value="true" />
    <option name="ADD_SOURCE_ROOTS" value="true" />
    <option name="SCRIPT_NAME" value={quoteattr(str(instance.odoo_bin))} />
    <option name="PARAMETERS" value={quoteattr(f"-c {instance.config_path}")} />
    <option name="SHOW_COMMAND_LINE" value="false" />
    <option name="EMULATE_TERMINAL" value="false" />
    <option name="MODULE_MODE" value="false" />
    <method v="2" />
  </configuration>
</component>
"""


def pycharm_sdk_name(instance: Instance) -> str:
    return f"Python {instance.python} ({instance.name})"


def pycharm_module(instance: Instance) -> str:
    """Project module: the instance folder plus the Odoo source, so code navigation works."""
    roots = [instance.community_dir]
    if instance.enterprise_dir is not None:
        roots.append(instance.enterprise_dir)
    extra = "".join(
        f"""    <content url="file://{root}">
      <sourceFolder url="file://{root}" isTestSource="false" />
    </content>
"""
        for root in roots
    )
    return f"""\
<?xml version="1.0" encoding="UTF-8"?>
<module type="PYTHON_MODULE" version="4">
  <component name="NewModuleRootManager">
    <content url="file://$MODULE_DIR$/..">
      <sourceFolder url="file://$MODULE_DIR$/../custom" isTestSource="false" />
      <excludeFolder url="file://$MODULE_DIR$/../venv" />
      <excludeFolder url="file://$MODULE_DIR$/../data" />
      <excludeFolder url="file://$MODULE_DIR$/../logs" />
    </content>
{extra}    <orderEntry type="jdk" jdkName={quoteattr(pycharm_sdk_name(instance))} jdkType="Python SDK" />
    <orderEntry type="sourceFolder" forTests="false" />
  </component>
</module>
"""


def pycharm_modules(instance: Instance) -> str:
    return f"""\
<?xml version="1.0" encoding="UTF-8"?>
<project version="4">
  <component name="ProjectModuleManager">
    <modules>
      <module fileurl="file://$PROJECT_DIR$/.idea/{instance.name}.iml"
              filepath="$PROJECT_DIR$/.idea/{instance.name}.iml" />
    </modules>
  </component>
</project>
"""


def pycharm_misc(instance: Instance) -> str:
    return f"""\
<?xml version="1.0" encoding="UTF-8"?>
<project version="4">
  <component name="ProjectRootManager" version="2"
             project-jdk-name={quoteattr(pycharm_sdk_name(instance))} project-jdk-type="Python SDK" />
</project>
"""


def start_script(instance: Instance) -> str:
    return f"""\
#!/bin/sh
# Run Odoo "{instance.name}" in the foreground (Ctrl+C to stop). Extra args are passed on,
# e.g.  ./start.sh -u my_module
# An editor can attach a debugger on port {instance.debug_port} ("Attach to Odoo").
export ODOOBUDDY_DEBUG_PORT={instance.debug_port}
exec {instance.python_bin} {instance.odoo_bin} -c {instance.config_path} "$@"
"""


def vscode_tasks(instance: Instance) -> str:
    """Start Odoo in the editor's terminal as soon as the folder is opened."""
    task = {
        "label": f"Odoo: run {instance.name}",
        "type": "process",
        "command": str(instance.python_bin),
        "args": [str(instance.odoo_bin), "-c", str(instance.config_path)],
        "options": {
            "cwd": str(instance.instance_dir),
            "env": {"ODOOBUDDY_DEBUG_PORT": str(instance.debug_port)},
        },
        "isBackground": True,
        "problemMatcher": [],
        "runOptions": {"runOn": "folderOpen", "instanceLimit": 1},
        "presentation": {"reveal": "always", "panel": "dedicated", "clear": True},
    }
    return json.dumps({"version": "2.0.0", "tasks": [task]}, indent=4) + "\n"


def pycharm_startup(instance: Instance) -> str:
    """PyCharm "Startup Tasks" (Settings > Tools > Startup Tasks): run Odoo when the project opens."""
    name = f"Odoo {instance.version} ({instance.name})"
    return f"""\
<?xml version="1.0" encoding="UTF-8"?>
<project version="4">
  <component name="ProjectStartupSharedConfiguration">
    <configurations>
      <configuration id={quoteattr("Python." + name)} name={quoteattr(name)} />
    </configurations>
  </component>
</project>
"""


def zed_tasks(instance: Instance) -> str:
    task = {
        "label": f"Odoo: run {instance.name}",
        "command": str(instance.python_bin),
        "args": [str(instance.odoo_bin), "-c", str(instance.config_path)],
        "cwd": str(instance.instance_dir),
        "env": {"ODOOBUDDY_DEBUG_PORT": str(instance.debug_port)},
        "use_new_terminal": False,
        "allow_concurrent_runs": False,
        "reveal": "always",
    }
    return json.dumps([task], indent=2) + "\n"


def zed_debug(instance: Instance) -> str:
    configs = [
        {
            "label": f"Attach to Odoo ({instance.name})",
            "adapter": "Debugpy",
            "request": "attach",
            "connect": {"host": "127.0.0.1", "port": instance.debug_port},
            "justMyCode": False,
        },
        {
            "label": f"Debug Odoo from start ({instance.name})",
            "adapter": "Debugpy",
            "request": "launch",
            "program": str(instance.odoo_bin),
            "args": ["-c", str(instance.config_path)],
            "cwd": str(instance.instance_dir),
            "python": str(instance.python_bin),
            "justMyCode": False,
        },
    ]
    return json.dumps(configs, indent=2) + "\n"


def zed_settings(instance: Instance) -> str:
    settings = {
        "file_scan_exclusions": ["**/.git", "**/__pycache__", "venv", "data"],
        "languages": {"Python": {"language_servers": ["pyright", "..."]}},
        "lsp": {
            "pyright": {
                "settings": {
                    "python": {"pythonPath": str(instance.python_bin)},
                    "python.analysis": {
                        "extraPaths": [str(instance.community_dir)] + [str(p) for p in addons_path(instance)]
                    },
                }
            }
        },
    }
    return json.dumps(settings, indent=2) + "\n"


# Imported at Python start-up (via a .pth file in the instance's venv) for odoo-bin only:
# 1. Odoo restarts itself (dev-mode reload, module installs) by exec'ing plain "python", which
#    is looked up on PATH - outside an activated venv that is the *system* Python, so the
#    restarted Odoo crashes with missing packages. Putting the venv's bin/ first fixes that.
# 2. With ODOOBUDDY_DEBUG_PORT set, Odoo listens for debuggers there - again after every
#    restart, which a normal debug launch cannot survive.
DEBUG_HOOK = '''"""Added by odoobuddy: keeps Odoo's self-restart inside this venv and lets
an editor attach a debugger to a running Odoo."""

import os
import sys


def _is_odoo_server():
    if not sys.argv or not sys.argv[0].endswith("odoo-bin"):
        return False
    return not (len(sys.argv) > 1 and sys.argv[1] == "shell")


def _use_this_python_on_restart():
    bindir = os.path.dirname(sys.executable)
    paths = [p for p in os.environ.get("PATH", "").split(os.pathsep) if p and p != bindir]
    os.environ["PATH"] = os.pathsep.join([bindir, *paths])
    os.environ["VIRTUAL_ENV"] = sys.prefix


def _listen():
    port = os.environ.get("ODOOBUDDY_DEBUG_PORT")
    if not port:
        return
    os.environ.setdefault("PYDEVD_DISABLE_FILE_VALIDATION", "1")
    try:
        import debugpy

        debugpy.configure(subProcess=False)  # Odoo re-execs itself; this hook re-attaches instead
        debugpy.listen(("127.0.0.1", int(port)))
    except Exception as exc:  # never stop Odoo from starting
        sys.stderr.write(f"odoobuddy: debugger not available on port {port}: {exc}\\n")


if _is_odoo_server():
    _use_this_python_on_restart()
    _listen()
'''
DEBUG_HOOK_PTH = "import _odoobuddy_debug\n"
